fn main() {
    let v1 = vec![1, 2, 3];
    let mut v1_iter = v1.iter();

    assert_eq!(v1_iter.next(), Some(&1));
    assert_eq!(v1_iter.next(), Some(&2));
    assert_eq!(v1_iter.next(), Some(&3));
    assert_eq!(v1_iter.next(), None);
    println!("done");
}

fn main() {
    let v = vec![3, 1, 4, 1, 5, 9, 2, 6];

    let total: i32 = v.iter().sum();
    let count = v.iter().count();
    let biggest = v.iter().max();
    let any_even = v.iter().any(|x| x % 2 == 0);
    let all_small = v.iter().all(|&x| x < 10);
    let first_big = v.iter().find(|&&x| x > 4);
    let pos = v.iter().position(|&x| x == 9);
    let product = v.iter().fold(1, |acc, x| acc * x);

    println!("{total} {count} {biggest:?} {any_even} {all_small}");
    println!("{first_big:?} {pos:?} {product}");
}

fn main() {
    let v1: Vec<i32> = vec![1, 2, 3];
    v1.iter().map(|x| x + 1);
}

fn main() {
    let names = ["ada", "grace", "linus", "barbara"];
    let years = [1815, 1906, 1969, 1939];

    let upper: Vec<String> = names.iter().map(|n| n.to_uppercase()).collect();
    println!("{upper:?}");

    let long: Vec<&str> = names.iter().copied().filter(|n| n.len() > 4).collect();
    println!("{long:?}");

    for (i, (name, year)) in names.iter().zip(years).enumerate().skip(1).take(2) {
        println!("{i}: {name} ({year})");
    }

    let numbers: Vec<i32> = "4, x, 8, 15, ?, 16"
        .split(", ")
        .filter_map(|s| s.parse().ok())
        .collect();
    println!("{numbers:?}");

    let letters: String = names.iter().flat_map(|n| n.chars().take(1)).collect();
    println!("{letters}");

    let evens_squared: i32 = (1..=10).filter(|n| n % 2 == 0).map(|n| n * n).sum();
    println!("{evens_squared}");
}

#[derive(PartialEq, Debug)]
struct Shoe {
    size: u32,
    style: String,
}

fn shoes_in_size(shoes: Vec<Shoe>, shoe_size: u32) -> Vec<Shoe> {
    shoes.into_iter().filter(|s| s.size == shoe_size).collect()
}

fn main() {
    let shoes = vec![
        Shoe { size: 10, style: String::from("sneaker") },
        Shoe { size: 13, style: String::from("sandal") },
        Shoe { size: 10, style: String::from("boot") },
    ];
    println!("{:?}", shoes_in_size(shoes, 10));
}

struct Fibonacci {
    curr: u64,
    next: u64,
}

impl Iterator for Fibonacci {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        let new_next = self.curr.checked_add(self.next)?;
        let result = self.curr;
        self.curr = self.next;
        self.next = new_next;
        Some(result)
    }
}

fn fibonacci() -> Fibonacci {
    Fibonacci { curr: 0, next: 1 }
}

fn main() {
    let first: Vec<u64> = fibonacci().take(10).collect();
    println!("{first:?}");
    let even_sum: u64 = fibonacci().take_while(|&x| x < 4_000_000).filter(|x| x % 2 == 0).sum();
    println!("{even_sum}");
    println!("{} terms fit in a u64", fibonacci().count());
}

fn main() {
    let users = [("alice", 31, true), ("bob", 17, false), ("carol", 45, true), ("dave", 12, false)];

    // names of active users, uppercased
    let mut active = Vec::new();
    for (name, _, is_active) in users {
        if is_active {
            active.push(name.to_uppercase());
        }
    }
    println!("{active:?}");

    // total length of names of users under 18
    let mut total = 0;
    for (name, age, _) in users {
        if age < 18 {
            total += name.len();
        }
    }
    println!("{total}");

    // name of the oldest user
    let mut oldest: Option<(&str, u32)> = None;
    for (name, age, _) in users {
        match oldest {
            Some((_, a)) if a >= age => {}
            _ => oldest = Some((name, age)),
        }
    }
    println!("{:?}", oldest.map(|(n, _)| n));
}
